"""Drafting, submitting, and reviewing expense reports."""
from typing import Optional

from . import lines, reports, routing
from .audit import Entry, Subject
from .budget import department_spend
from .errors import Failure, FailureCode
from .host import Store
from .ids import Badge, Period, ReportId, Role
from .lines import Line
from .reports import Report, ReportStatus
from .staff import Staff


def open_draft(store: Store, badge: Badge, period: Period, first_line: Line) -> ReportId:
    who = store.staff(badge)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    if store.period_closed(period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    id = store.next_id()
    store.save_report(Report(id, badge, who.department, period, (first_line,), ReportStatus.DRAFT))
    return id


def add_line(store: Store, report_id: ReportId, badge: Badge, line: Line) -> None:
    r = _own(store, report_id, badge)
    if not reports.editable(r):
        raise Failure(FailureCode.CONFLICT, "the report is not editable")
    if len(r.lines) >= reports.MAX_LINES:
        raise Failure(FailureCode.INVALID_INPUT, "a report holds at most 50 lines")
    store.save_report(reports.add_line(r, line))


def submit(store: Store, report_id: ReportId, badge: Badge) -> None:
    r = _own(store, report_id, badge)
    if r.status is not ReportStatus.DRAFT:
        raise Failure(FailureCode.CONFLICT, "the report is not a draft")
    _open_and_valid(store, r)
    store.save_report(reports.submit(r))
    store.append_audit(Entry(badge, Subject.REPORT, r.id, ReportStatus.DRAFT, ReportStatus.SUBMITTED, "submitted"))


def resubmit(store: Store, report_id: ReportId, badge: Badge) -> None:
    r = _own(store, report_id, badge)
    if r.status is not ReportStatus.CHANGES_REQUESTED:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting changes")
    _open_and_valid(store, r)
    store.save_report(reports.resubmit(r))
    store.append_audit(Entry(badge, Subject.REPORT, r.id, ReportStatus.CHANGES_REQUESTED, ReportStatus.SUBMITTED, "resubmitted"))


def approve(store: Store, report_id: ReportId, approver: Badge) -> ReportStatus:
    r, who = _gate(store, report_id, approver)
    if len(r.approvals) + 1 >= routing.steps_for(lines.total(r.lines)):
        return _final_approval(store, r, who)
    store.save_report(reports.add_approval(r, who.badge))
    store.append_audit(Entry(who.badge, Subject.REPORT, r.id, ReportStatus.SUBMITTED, ReportStatus.SUBMITTED, "approved; awaiting the next approver"))
    return ReportStatus.SUBMITTED


def reject(store: Store, report_id: ReportId, approver: Badge, reason: str) -> None:
    r, who = _gate(store, report_id, approver)
    store.save_report(reports.reject(r))
    store.append_audit(Entry(who.badge, Subject.REPORT, r.id, ReportStatus.SUBMITTED, ReportStatus.REJECTED, reason))


def request_changes(store: Store, report_id: ReportId, approver: Badge, reason: str) -> None:
    r, who = _gate(store, report_id, approver)
    store.save_report(reports.request_changes(r))
    store.append_audit(Entry(who.badge, Subject.REPORT, r.id, ReportStatus.SUBMITTED, ReportStatus.CHANGES_REQUESTED, reason))


def may_act(store: Store, r, who: Staff) -> bool:
    """Is `who` the required approver for the next step of `r`, a report or an advance? Raises Conflict when no one can be."""
    required = _required_for(store, r)
    if required is None:
        return who.role is Role.FINANCE
    return who.badge == required


def _own(store: Store, report_id: ReportId, badge: Badge) -> Report:
    who = store.staff(badge)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    r = store.report(report_id)
    if r.badge != badge:
        raise Failure(FailureCode.UNAUTHORIZED, "only the submitter may act on this report")
    return r


def _open_and_valid(store: Store, r: Report) -> None:
    if store.period_closed(r.period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    if not lines.all_valid(r.lines):
        raise Failure(FailureCode.INVALID_INPUT, "a line is over its limit or lacks a required receipt")


def _gate(store: Store, report_id: ReportId, approver: Badge) -> tuple[Report, Staff]:
    who = store.staff(approver)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    r = store.report(report_id)
    if r.status is not ReportStatus.SUBMITTED:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting approval")
    if store.period_closed(r.period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    if who.badge == r.badge:
        raise Failure(FailureCode.UNAUTHORIZED, "a report cannot be approved by its submitter")
    if not may_act(store, r, who):
        raise Failure(FailureCode.UNAUTHORIZED, "not this report's next approver")
    return r, who


def within_budget(store: Store, department, period, amount: int) -> bool:
    return department_spend(store, department, period) + amount <= store.department(department).budget


def _required_for(store: Store, r) -> Optional[Badge]:
    """The badge required for the next step, or None when any active finance staff member will do."""
    role = routing.role_for(len(r.approvals) + 1)
    if role is Role.FINANCE:
        return None
    if role is Role.SUPERVISOR:
        submitter = store.staff(r.badge)
        if submitter.supervisor is None:
            raise Failure(FailureCode.CONFLICT, "the submitter has no supervisor")
        return _stand_in(store, submitter.supervisor)
    return _stand_in(store, store.department(r.department).director)


def _stand_in(store: Store, required: Badge) -> Badge:
    person = store.staff(required)
    if person.active:
        return required
    if person.supervisor is not None and store.staff(person.supervisor).active:
        return person.supervisor
    raise Failure(FailureCode.CONFLICT, f"no active approver stands in for {required}")


def _final_approval(store: Store, r: Report, who: Staff) -> ReportStatus:
    within = within_budget(store, r.department, r.period, lines.budgeted_total(r.lines))
    if not within and who.role is not Role.FINANCE:
        raise Failure(FailureCode.CONFLICT, "the department budget for this period would be exceeded")
    store.save_report(reports.approve(r))
    store.append_audit(Entry(who.badge, Subject.REPORT, r.id, ReportStatus.SUBMITTED, ReportStatus.APPROVED,
                             "approved" if within else "approved; budget override"))
    return ReportStatus.APPROVED

from dataclasses import dataclass, replace
from enum import Enum
from typing import Optional, Sequence

from .errors import Failure, FailureCode
from .ids import Badge, DepartmentId, Period, ReportId
from .lines import Line

MAX_LINES = 50
MAX_APPROVALS = 2      # a third approval completes the chain, so a Submitted report never holds three


class ReportStatus(Enum):
    DRAFT = "Draft"
    SUBMITTED = "Submitted"
    APPROVED = "Approved"
    REJECTED = "Rejected"
    CHANGES_REQUESTED = "ChangesRequested"
    PAID = "Paid"


TRANSITIONS = {
    ReportStatus.DRAFT: {ReportStatus.SUBMITTED},
    ReportStatus.SUBMITTED: {ReportStatus.APPROVED, ReportStatus.REJECTED, ReportStatus.CHANGES_REQUESTED},
    ReportStatus.CHANGES_REQUESTED: {ReportStatus.SUBMITTED},
    ReportStatus.APPROVED: {ReportStatus.PAID},
    ReportStatus.REJECTED: set(),
    ReportStatus.PAID: set(),
}


@dataclass(frozen=True)
class Report:
    id: ReportId
    badge: Badge
    department: DepartmentId
    period: Period
    lines: Sequence[Line]
    status: ReportStatus
    approvals: Sequence[Badge] = ()
    reference: Optional[str] = None      # set only once Paid


def _enter(r: Report, status: ReportStatus, **fields) -> Report:
    if status not in TRANSITIONS[r.status]:
        raise Failure(FailureCode.CONFLICT, f"a {r.status.value} report cannot become {status.value}")
    return replace(r, status=status, **fields)


def editable(r: Report) -> bool:
    return r.status in (ReportStatus.DRAFT, ReportStatus.CHANGES_REQUESTED)


def add_line(r: Report, line: Line) -> Report:
    if not editable(r) or len(r.lines) >= MAX_LINES:
        raise Failure(FailureCode.CONFLICT, "the report cannot take another line")
    return replace(r, lines=(*r.lines, line))


def submit(r: Report) -> Report:
    return _enter(r, ReportStatus.SUBMITTED, approvals=())


def add_approval(r: Report, who: Badge) -> Report:
    if r.status is not ReportStatus.SUBMITTED or len(r.approvals) >= MAX_APPROVALS:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting another approval")
    return replace(r, approvals=(*r.approvals, who))


def approve(r: Report) -> Report:
    return _enter(r, ReportStatus.APPROVED)


def reject(r: Report) -> Report:
    return _enter(r, ReportStatus.REJECTED)


def request_changes(r: Report) -> Report:
    return _enter(r, ReportStatus.CHANGES_REQUESTED, approvals=())


def resubmit(r: Report) -> Report:
    return _enter(r, ReportStatus.SUBMITTED, approvals=())


def pay(r: Report, reference: str) -> Report:
    return _enter(r, ReportStatus.PAID, reference=reference)


def counts_as_spend(r: Report) -> bool:
    return r.status in (ReportStatus.APPROVED, ReportStatus.PAID)

from typing import Sequence

from . import advances
from .advances import Advance
from .host import Store
from .ids import DepartmentId, Period
from .lines import budgeted_total
from .reports import Report, counts_as_spend


def spend_of(reports: Sequence[Report], advs: Sequence[Advance]) -> int:
    return (sum(budgeted_total(r.lines) for r in reports if counts_as_spend(r))
            + sum(a.amount for a in advs if advances.counts_as_spend(a)))


def department_spend(store: Store, department: DepartmentId, period: Period) -> int:
    return spend_of(store.reports_for(department, period), store.advances_for(department, period))

"""The records the grown desk keeps beside reports: vendors, purchase orders, card transactions, delegations, cost centers, card limits, policy exceptions."""
from dataclasses import dataclass, replace
from enum import Enum
from typing import Optional, Sequence

from .errors import Failure, FailureCode
from .ids import Badge, Category, DepartmentId, Money, Period, ReportId

VendorId = str
PoId = str
TxnId = str
DelegationId = str
CostCenterId = str
EntityId = str
ExceptionId = str

MAX_TEXT = 200
MAX_PO_APPROVALS = 2   # as a report's: the last approval completes the chain


class Region(Enum):
    ISLAND = "Island"
    MAINLAND = "Mainland"
    OFFSITE = "Offsite"


class Vehicle(Enum):
    CAR = "Car"
    TRUCK = "Truck"
    BOAT = "Boat"


class PoStatus(Enum):
    REQUESTED = "Requested"
    APPROVED = "Approved"
    REJECTED = "Rejected"
    RECEIVED = "Received"
    CLOSED = "Closed"


class CardStatus(Enum):
    OPEN = "Open"
    MATCHED = "Matched"
    DISPUTED = "Disputed"


class ExceptionStatus(Enum):
    PENDING = "Pending"
    GRANTED = "Granted"
    DENIED = "Denied"


PER_DIEM = {Region.ISLAND: 9_000, Region.MAINLAND: 6_000, Region.OFFSITE: 12_000}     # cents per day
MILEAGE = {Vehicle.CAR: 60, Vehicle.TRUCK: 90, Vehicle.BOAT: 250}                     # cents per kilometre

PO_TRANSITIONS = {
    PoStatus.REQUESTED: {PoStatus.APPROVED, PoStatus.REJECTED},
    PoStatus.APPROVED: {PoStatus.RECEIVED},
    PoStatus.RECEIVED: {PoStatus.CLOSED},
    PoStatus.REJECTED: set(),
    PoStatus.CLOSED: set(),
}

CARD_TRANSITIONS = {
    CardStatus.OPEN: {CardStatus.MATCHED, CardStatus.DISPUTED},
    CardStatus.DISPUTED: {CardStatus.OPEN},
    CardStatus.MATCHED: set(),
}

EXCEPTION_TRANSITIONS = {
    ExceptionStatus.PENDING: {ExceptionStatus.GRANTED, ExceptionStatus.DENIED},
    ExceptionStatus.GRANTED: set(),
    ExceptionStatus.DENIED: set(),
}


@dataclass(frozen=True)
class Vendor:
    id: VendorId
    name: str
    active: bool


@dataclass(frozen=True)
class PurchaseOrder:
    id: PoId
    vendor: VendorId
    requested_by: Badge
    department: DepartmentId
    period: Period
    amount: Money
    status: PoStatus
    approvals: Sequence[Badge] = ()
    received: Money = 0                  # set only once Received


@dataclass(frozen=True)
class CardTxn:
    id: TxnId
    badge: Badge                         # the card holder
    period: Period
    amount: Money
    category: Category
    merchant: str
    status: CardStatus
    matched: Optional[ReportId] = None


@dataclass(frozen=True)
class Delegation:
    id: DelegationId
    delegator: Badge
    delegate: Badge
    first: Period
    last: Period
    revoked: bool = False


@dataclass(frozen=True)
class Entity:
    id: EntityId
    name: str


@dataclass(frozen=True)
class CostCenter:
    id: CostCenterId
    entity: EntityId
    name: str


@dataclass(frozen=True)
class CardLimit:
    badge: Badge
    limit: Money


@dataclass(frozen=True)
class PolicyException:
    id: ExceptionId
    report: ReportId
    position: int                        # 1-based line position
    badge: Badge                         # who asked
    reason: str
    status: ExceptionStatus
    decided_by: Optional[Badge] = None


def _move(record, transitions, status, **fields):
    if status not in transitions[record.status]:
        raise Failure(FailureCode.CONFLICT, f"a {record.status.value} record cannot become {status.value}")
    return replace(record, status=status, **fields)


def advance_po(po: PurchaseOrder, status: PoStatus, **fields) -> PurchaseOrder:
    return _move(po, PO_TRANSITIONS, status, **fields)


def add_po_approval(po: PurchaseOrder, who: Badge) -> PurchaseOrder:
    if po.status is not PoStatus.REQUESTED or len(po.approvals) >= MAX_PO_APPROVALS:
        raise Failure(FailureCode.CONFLICT, "the purchase order is not awaiting another approval")
    return replace(po, approvals=(*po.approvals, who))


def advance_txn(t: CardTxn, status: CardStatus, **fields) -> CardTxn:
    return _move(t, CARD_TRANSITIONS, status, **fields)


def settle_exception(e: PolicyException, status: ExceptionStatus, decided_by: Badge) -> PolicyException:
    return _move(e, EXCEPTION_TRANSITIONS, status, decided_by=decided_by)


def in_force(d: Delegation, period: Period) -> bool:
    return not d.revoked and d.first <= period <= d.last


def committed(po: PurchaseOrder) -> Money:
    if po.status is PoStatus.APPROVED:
        return po.amount
    if po.status in (PoStatus.RECEIVED, PoStatus.CLOSED):
        return po.received
    return 0


def commitments_of(pos: Sequence[PurchaseOrder]) -> int:
    return sum(committed(po) for po in pos)


def text_ok(text: str) -> bool:
    return 1 <= len(text) <= MAX_TEXT

"""Raising, approving, receiving, and closing purchase orders against a department's PO allowance."""
from . import records, routing
from .checks import active_staff, finance_staff
from .errors import Failure, FailureCode
from .host import Store
from .ids import MONEY_MAX, Badge, DepartmentId, Money, Period, Role
from .records import PoId, PoStatus, PurchaseOrder, VendorId, commitments_of, in_force
from .registry import Registry
from .staff import Staff


def raise_po(store: Store, reg: Registry, badge: Badge, vendor_id: VendorId, amount: Money, period: Period) -> PoId:
    who = active_staff(store, badge)
    if not reg.vendor(vendor_id).active:
        raise Failure(FailureCode.CONFLICT, "the vendor is not active")
    if not 1 <= amount <= MONEY_MAX:
        raise Failure(FailureCode.INVALID_INPUT, "a purchase order is for at least one cent")
    if store.period_closed(period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    id = store.next_id()
    reg.save_po(PurchaseOrder(id, vendor_id, who.badge, who.department, period, amount, PoStatus.REQUESTED, (), 0))
    return id


def approve_po(store: Store, reg: Registry, po_id: PoId, approver: Badge) -> PoStatus:
    po, who = _gate(store, reg, po_id, approver)
    if len(po.approvals) + 1 >= routing.steps_for(po.amount):
        if commitments_of(reg.pos_for(po.department, po.period)) + po.amount > reg.allowance(po.department, po.period):
            raise Failure(FailureCode.CONFLICT, "the department's PO allowance for this period would be exceeded")
        reg.save_po(records.advance_po(po, PoStatus.APPROVED))
        return PoStatus.APPROVED
    reg.save_po(records.add_po_approval(po, who.badge))
    return PoStatus.REQUESTED


def reject_po(store: Store, reg: Registry, po_id: PoId, approver: Badge) -> None:
    po, _ = _gate(store, reg, po_id, approver)
    reg.save_po(records.advance_po(po, PoStatus.REJECTED))


def receive_po(store: Store, reg: Registry, po_id: PoId, badge: Badge, received_amount: Money) -> None:
    active_staff(store, badge)
    po = reg.po(po_id)
    if po.requested_by != badge:
        raise Failure(FailureCode.UNAUTHORIZED, "only the requester may receive a purchase order")
    if po.status is not PoStatus.APPROVED:
        raise Failure(FailureCode.CONFLICT, "the purchase order is not approved")
    if not 1 <= received_amount <= po.amount:
        raise Failure(FailureCode.INVALID_INPUT, "the received amount is from one cent to the ordered amount")
    reg.save_po(records.advance_po(po, PoStatus.RECEIVED, received=received_amount))


def close_po(store: Store, reg: Registry, po_id: PoId, finance_badge: Badge) -> None:
    finance_staff(store, finance_badge)
    po = reg.po(po_id)
    if po.status is not PoStatus.RECEIVED:
        raise Failure(FailureCode.CONFLICT, "the purchase order is not received")
    reg.save_po(records.advance_po(po, PoStatus.CLOSED))


def po_commitments(store: Store, reg: Registry, department: DepartmentId, period: Period) -> int:
    dept = store.department(department)
    return commitments_of(reg.pos_for(dept.id, period))


def accepted_for(store: Store, reg: Registry, po: PurchaseOrder, who: Staff) -> bool:
    """May `who` act on the PO's next step? Raises Conflict when no one can."""
    role = routing.role_for(len(po.approvals) + 1)
    if role is Role.FINANCE:
        return who.role is Role.FINANCE
    if role is Role.SUPERVISOR:
        requester = store.staff(po.requested_by)
        if requester.supervisor is None:
            raise Failure(FailureCode.CONFLICT, "the requester has no supervisor")
        required = requester.supervisor
    else:
        required = store.department(po.department).director
    person = store.staff(required)
    delegates = [d.delegate for d in reg.delegations_from(person.badge) if in_force(d, po.period)]
    if person.active:
        return who.badge == person.badge or who.badge in delegates
    if not delegates:
        raise Failure(FailureCode.CONFLICT, f"{required} is inactive and has no delegate in force")
    return who.badge in delegates


def _gate(store: Store, reg: Registry, po_id: PoId, approver: Badge) -> tuple[PurchaseOrder, Staff]:
    who = active_staff(store, approver)
    po = reg.po(po_id)
    if po.status is not PoStatus.REQUESTED:
        raise Failure(FailureCode.CONFLICT, "the purchase order is not awaiting approval")
    if store.period_closed(po.period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    if who.badge == po.requested_by:
        raise Failure(FailureCode.UNAUTHORIZED, "a purchase order cannot be approved by its requester")
    if not accepted_for(store, reg, po, who):
        raise Failure(FailureCode.UNAUTHORIZED, "not this purchase order's next approver")
    return po, who

from .ids import Role

SUPERVISOR_ONLY_UP_TO = 50_000
DIRECTOR_UP_TO = 500_000

STEP_ROLES = (Role.SUPERVISOR, Role.DIRECTOR, Role.FINANCE)


def steps_for(total: int) -> int:
    if total <= SUPERVISOR_ONLY_UP_TO:
        return 1
    if total <= DIRECTOR_UP_TO:
        return 2
    return 3


def role_for(step: int) -> Role:
    return STEP_ROLES[step - 1]

"""Cash advances: requested before a trip, approved like a report, paid, then settled against the trip's report."""
from dataclasses import dataclass, replace
from enum import Enum
from typing import Optional, Sequence

from .errors import Failure, FailureCode
from .ids import Badge, DepartmentId, Money, Period, ReportId

OUTSTANDING_AFTER = 2      # periods after its own that a paid advance may stay unsettled


class AdvanceStatus(Enum):
    REQUESTED = "Requested"
    APPROVED = "Approved"
    PAID = "Paid"
    SETTLED = "Settled"


TRANSITIONS = {
    AdvanceStatus.REQUESTED: {AdvanceStatus.APPROVED},
    AdvanceStatus.APPROVED: {AdvanceStatus.PAID},
    AdvanceStatus.PAID: {AdvanceStatus.SETTLED},
    AdvanceStatus.SETTLED: set(),
}


@dataclass(frozen=True)
class Advance:
    id: ReportId
    badge: Badge
    department: DepartmentId
    period: Period
    amount: Money
    status: AdvanceStatus
    approvals: Sequence[Badge] = ()
    reference: Optional[str] = None      # set once Paid
    owed: Optional[int] = None           # set once Settled: what the staff member owes back


def _enter(a: Advance, status: AdvanceStatus, **fields) -> Advance:
    if status not in TRANSITIONS[a.status]:
        raise Failure(FailureCode.CONFLICT, f"a {a.status.value} advance cannot become {status.value}")
    return replace(a, status=status, **fields)


def add_approval(a: Advance, who: Badge) -> Advance:
    if a.status is not AdvanceStatus.REQUESTED:
        raise Failure(FailureCode.CONFLICT, "the advance is not awaiting approval")
    return replace(a, approvals=(*a.approvals, who))


def approve(a: Advance) -> Advance:
    return _enter(a, AdvanceStatus.APPROVED)


def pay(a: Advance, reference: str) -> Advance:
    return _enter(a, AdvanceStatus.PAID, reference=reference)


def settle(a: Advance, owed: int) -> Advance:
    return _enter(a, AdvanceStatus.SETTLED, owed=owed)


def counts_as_spend(a: Advance) -> bool:
    return a.status in (AdvanceStatus.APPROVED, AdvanceStatus.PAID)


def outstanding(a: Advance, today: Period) -> bool:
    return a.status is AdvanceStatus.PAID and a.period + OUTSTANDING_AFTER < today

from dataclasses import dataclass
from typing import Sequence

from .ids import Category, Money

MAX_LINES = 50


@dataclass(frozen=True)
class Line:
    category: Category
    amount: Money
    description: str
    receipt: bool


@dataclass(frozen=True)
class Policy:
    limit: Money
    receipt_over: Money
    budgeted: bool


POLICIES = {
    Category.FEED: Policy(200_000, 2_500, True),
    Category.VETERINARY: Policy(500_000, 2_500, True),
    Category.CONTAINMENT: Policy(1_000_000, 5_000, True),
    Category.EQUIPMENT: Policy(300_000, 2_500, True),
    Category.TRAVEL: Policy(150_000, 2_500, True),
    Category.OTHER: Policy(50_000, 2_500, True),
}


def policy_for(category: Category) -> Policy:
    return POLICIES[category]


def line_valid(line: Line) -> bool:
    policy = policy_for(line.category)
    return line.amount <= policy.limit and (line.amount <= policy.receipt_over or line.receipt)


def all_valid(lines: Sequence[Line]) -> bool:
    return 1 <= len(lines) <= MAX_LINES and all(line_valid(l) for l in lines)


def total(lines: Sequence[Line]) -> int:
    return sum(l.amount for l in lines)


def budgeted_total(lines: Sequence[Line]) -> int:
    return sum(l.amount for l in lines if policy_for(l.category).budgeted)

"""Per-holder card limits, and who went over theirs in a period."""
from .checks import finance_staff
from .errors import Failure, FailureCode
from .host import Store
from .ids import MONEY_MAX, Badge, Money, Period
from .records import CardLimit, CardStatus
from .registry import Registry


def set_card_limit(store: Store, reg: Registry, finance_badge: Badge, badge: Badge, limit: Money) -> None:
    finance_staff(store, finance_badge)
    holder = store.staff(badge)
    if not 0 <= limit <= MONEY_MAX:
        raise Failure(FailureCode.INVALID_INPUT, "a card limit is 0 to 1,000,000,000 cents")
    reg.save_card_limit(CardLimit(holder.badge, limit))


def over_limit(reg: Registry, period: Period) -> list[Badge]:
    spent: dict[Badge, int] = {}                   # insertion order is first appearance
    for t in reg.txns_for(period):
        if t.status is not CardStatus.DISPUTED:
            spent[t.badge] = spent.get(t.badge, 0) + t.amount
    over = []
    for badge, amount in spent.items():
        try:
            limit = reg.card_limit(badge).limit
        except Failure as f:
            if f.code is not FailureCode.NOT_FOUND:        # no limit set: never over
                raise
            continue
        if amount > limit:
            over.append(badge)
    return over
